113→  // 와일드카드 체크
114→  const wildcard = db
115→    .prepare("SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = 'view'")
116→    .get(role) as { allowed: number } | undefined;
117→
118→  if (wildcard?.allowed === 1) {
119→    return [
120→      "dashboard.summary", "dashboard.allocation", "dashboard.progress",
121→      "candidates", "procedures", "actions",
122→      "admin.data-sheet", "admin.workflow",
