"use client";

type KpiData = {
  total: number;
  inProgress: number;
  completed: number;
  waiting: number;
};

type ActivityItem = {
  id: number;
  deptName: string;
  description: string;
  status: "complete" | "progress" | "waiting";
  timeAgo: string;
};

type Props = {
  kpi: KpiData;
  recentActivity: ActivityItem[];
};

export default function SummaryPage({ kpi, recentActivity }: Props) {
  const statusColor: Record<string, string> = {
    complete: "var(--status-complete)",
    progress: "var(--status-progress)",
    waiting: "var(--text-disabled)",
  };

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <div>
          <h2 style={{ fontSize: 18, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>
            현황 요약
          </h2>
          <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "2px 0 0" }}>
            2026년 1학기 교원채용
          </p>
        </div>
      </div>

      {/* KPI Cards */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 12, marginBottom: 20 }}>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--text-secondary)" }}>전체 채용건</div>
          <div style={{ fontSize: 28, fontWeight: 700, color: "var(--text-title)", marginTop: 2 }}>
            {kpi.total}
          </div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--text-secondary)" }}>진행 중</div>
          <div style={{ fontSize: 28, fontWeight: 700, color: "var(--gold)", marginTop: 2 }}>
            {kpi.inProgress}
          </div>
          <div style={{ fontSize: 10, color: "var(--text-secondary)", marginTop: 2 }}>
            {kpi.total > 0 ? ((kpi.inProgress / kpi.total) * 100).toFixed(1) : 0}%
          </div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--text-secondary)" }}>완료</div>
          <div style={{ fontSize: 28, fontWeight: 700, color: "var(--status-complete)", marginTop: 2 }}>
            {kpi.completed}
          </div>
          <div style={{ fontSize: 10, color: "var(--text-secondary)", marginTop: 2 }}>
            {kpi.total > 0 ? ((kpi.completed / kpi.total) * 100).toFixed(1) : 0}%
          </div>
        </div>
        <div className="card">
          <div style={{ fontSize: 11, color: "var(--text-secondary)" }}>대기</div>
          <div style={{ fontSize: 28, fontWeight: 700, color: "var(--text-secondary)", marginTop: 2 }}>
            {kpi.waiting}
          </div>
        </div>
      </div>

      {/* Recent Activity */}
      <div className="card">
        <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text-body)", marginBottom: 14 }}>
          최근 활동
        </div>
        <div style={{ display: "flex", flexDirection: "column" }}>
          {recentActivity.length === 0 && (
            <div style={{ fontSize: 12, color: "var(--text-disabled)", padding: "10px 0" }}>
              최근 활동이 없습니다.
            </div>
          )}
          {recentActivity.map((item, i) => (
            <div
              key={item.id}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 12,
                padding: "10px 0",
                borderTop: i > 0 ? "1px solid var(--divider)" : "none",
              }}
            >
              <div
                style={{
                  width: 6,
                  height: 6,
                  background: statusColor[item.status],
                  borderRadius: "50%",
                  flexShrink: 0,
                }}
              />
              <div style={{ fontSize: 12, color: "var(--text-body)", flex: 1 }}>
                {item.deptName} — {item.description}
              </div>
              <div style={{ fontSize: 10, color: "var(--text-disabled)", flexShrink: 0 }}>
                {item.timeAgo}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

