  if (status.includes("심사") || status.includes("협의")) return "badge badge-review";
  if (status.includes("대기") || !status) return "badge badge-waiting";
  return "badge badge-progress";
}

function parseProgress(progressStr: string | null | number): number {
  if (progressStr === null || progressStr === undefined) return 0;
  const str = String(progressStr).replace("%", "");
  const num = Number.parseInt(str, 10);
  return Number.isNaN(num) ? 0 : num;
}

function getProgressBarColor(progress: number): string {
  if (progress >= 100) return "var(--status-complete)";
  if (progress >= 50) return "var(--status-progress)";
  return "var(--status-review)";
}

